import click
from click.testing import CliRunner

def test_fish_completion_multiline_help():
    @click.group()
    def cli():
        pass

    @cli.command()
    @click.option(
        "--opt",
        help="Line 1\nLine 2",
    )
    def cmd(opt):
        pass

    runner = CliRunner()
    result = runner.invoke(
        cli,
        [], # No command needed, just the app itself to generate completions
        env={
            "_CLICK_COMPLETE": "fish_source",
            "COMP_WORDS": "cli --",
            "COMP_CWORD": "1",
        },
    )

    assert result.exit_code == 0
    # The expected problematic output format for fish completion
    # is 'plain,<option_name>\n<help_text_line1>\n<help_text_line2>'
    # This is what fish's string split would choke on.
    # The test should FAIL if this problematic line IS present (buggy behavior).
    # It should PASS if this problematic line is NOT present (fixed behavior).
    expected_problematic_line = "plain,--opt\nLine 1\nLine 2"
    assert expected_problematic_line not in result.output
